-- v0.1 schema: ARCHITECTURE.md §4. Ids are UUIDv7 generated by the application.

create extension if not exists citext;

-- updated_at is maintained by trigger, never set in code.
create function set_updated_at() returns trigger
language plpgsql as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

create type user_role as enum ('user', 'organizer', 'seed_admin', 'admin');
create type dancer_source as enum ('seed', 'organizer', 'self');
create type claim_status as enum ('pending', 'approved', 'rejected');
create type event_status as enum ('draft', 'published', 'registration_closed', 'completed', 'cancelled');
create type entry_status as enum ('pending', 'confirmed', 'withdrawn');
create type staff_role as enum ('judge', 'dj', 'mc', 'organizer', 'other');
create type battle_format as enum ('team', 'seven_to_smoke', 'na');
create type battle_gender as enum ('bboy', 'bgirl', 'mixed');
create type battle_age as enum ('kids', 'adult', 'na');
create type bracket_stage as enum ('prelims', 'top64', 'top32', 'top16', 'top8', 'top4', 'top2', 'winner', 'na');

create table app_users (
  id uuid primary key,
  email citext not null unique,
  password_hash text,
  google_sub text unique,
  display_name text not null,
  role user_role not null default 'user',
  email_verified_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table sessions (
  id uuid primary key,
  user_id uuid not null references app_users(id) on delete cascade,
  expires_at timestamptz not null,
  created_at timestamptz not null default now()
);
create index on sessions (user_id);

create table dancers (
  id uuid primary key,
  user_id uuid unique references app_users(id) on delete set null,
  dancer_name text not null,
  aliases text[] not null default '{}',
  real_name text,
  country char(2) not null,
  country2 char(2),
  city text,
  bio text,
  instagram_handle text,
  source dancer_source not null default 'organizer',
  notable boolean not null default false,
  verified_at timestamptz,
  avatar_url text,
  merged_into_id uuid references dancers(id),
  created_by uuid references app_users(id),
  deleted_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index on dancers (lower(dancer_name));
create index on dancers using gin (aliases);
create index on dancers (country);
create unique index dancers_instagram_handle_key
  on dancers (lower(instagram_handle))
  where instagram_handle is not null and deleted_at is null and merged_into_id is null;

create table dancer_claims (
  id uuid primary key,
  dancer_id uuid not null references dancers(id),
  user_id uuid not null references app_users(id),
  code text not null,
  status claim_status not null default 'pending',
  reviewed_by uuid references app_users(id),
  reviewed_at timestamptz,
  created_at timestamptz not null default now()
);
create index on dancer_claims (status, created_at);
create unique index dancer_claims_one_pending_key
  on dancer_claims (dancer_id, user_id) where status = 'pending';

create table dancer_edits (
  id uuid primary key,
  dancer_id uuid not null references dancers(id),
  user_id uuid not null references app_users(id),
  field text not null,
  old_value text,
  new_value text,
  created_at timestamptz not null default now()
);
create index on dancer_edits (dancer_id, created_at);

create table crews (
  id uuid primary key,
  name text not null,
  country char(2),
  city text,
  instagram_handle text,
  deleted_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index on crews (lower(name));

create table crew_memberships (
  dancer_id uuid not null references dancers(id) on delete cascade,
  crew_id uuid not null references crews(id) on delete cascade,
  since date,                  -- null = unknown
  until date,                  -- null = current member
  -- Not a primary key: PK columns are forced NOT NULL and `since` is often unknown.
  unique nulls not distinct (dancer_id, crew_id, since)
);

create table events (
  id uuid primary key,
  organizer_id uuid not null references app_users(id),
  name text not null,
  slug text not null unique,
  description text,
  status event_status not null default 'draft',
  starts_on date not null,
  ends_on date not null,
  timezone text not null,
  venue_name text,
  address text,
  city text not null,
  country char(2) not null,
  lat double precision,
  lng double precision,
  registration_url text,
  instagram_url text,
  deleted_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (ends_on >= starts_on)
);
create index on events (status, starts_on);
create index on events (country);

create table battles (
  id uuid primary key,
  event_id uuid not null references events(id) on delete cascade,
  name text not null,
  format battle_format not null default 'team',
  team_size smallint check (team_size between 1 and 10),
  gender battle_gender not null default 'mixed',
  age battle_age not null default 'adult',
  age_min smallint check (age_min >= 0),
  age_max smallint,
  bracket_size smallint check (bracket_size in (2, 4, 8, 16, 32, 64)),
  max_entries int check (max_entries > 0),
  position smallint not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (age_max >= age_min),
  check (format <> 'team' or team_size is not null),
  check (age <> 'kids' or (age_max is not null and age_max <= 17)),
  check (age <> 'adult' or (age_min is not null and age_min >= 18))
);
create index on battles (event_id, position);

create table entries (
  id uuid primary key,
  battle_id uuid not null references battles(id) on delete cascade,
  crew_id uuid references crews(id),
  team_name text,
  status entry_status not null default 'pending',
  reached bracket_stage not null default 'na',
  final_rank int check (final_rank >= 1),
  video_url text,
  video_offset_seconds int check (video_offset_seconds >= 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index on entries (battle_id);

create table entry_members (
  entry_id uuid not null references entries(id) on delete cascade,
  dancer_id uuid not null references dancers(id),
  primary key (entry_id, dancer_id)
);

create table event_staff (
  event_id uuid not null references events(id) on delete cascade,
  dancer_id uuid not null references dancers(id),
  role staff_role not null,
  primary key (event_id, dancer_id, role)
);

create trigger set_updated_at before update on app_users for each row execute function set_updated_at();
create trigger set_updated_at before update on dancers for each row execute function set_updated_at();
create trigger set_updated_at before update on crews for each row execute function set_updated_at();
create trigger set_updated_at before update on events for each row execute function set_updated_at();
create trigger set_updated_at before update on battles for each row execute function set_updated_at();
create trigger set_updated_at before update on entries for each row execute function set_updated_at();
